<script setup>
import { computed, ref, nextTick, watch } from 'vue'
import { useRoute } from 'vue-router'
import { useDemo } from '../../stores/demo.js'
import { printReport } from '../../lib/exports.js'
import PageHeader from '../../components/PageHeader.vue'
import StatusBadge from '../../components/StatusBadge.vue'
import ReportFields from './visual/ReportFields.vue'
import { clone, today, display, userOptions, investigatorOptions } from './common.js'
import { maicGroups, initialFields, initializeFields } from './maic.js'
const route=useRoute(),store=useDemo(),draft=ref(null),error=ref(''),success=ref(''),stage=ref('1B'),openSections=ref({}),revisionsOpen=ref(false)
const event=computed(()=>store.getEvent(route.params.id))
const reports=computed(()=>store.visibleRecords('reports').filter(r=>r.eventId===event.value?.id && ['1B','2','3B'].includes(r.type)).sort((a,b)=>String(b.createdAt || b.date).localeCompare(String(a.createdAt || a.date)) || b.revision-a.revision))
const groups=computed(()=>maicGroups.filter(g=>g.stages.includes(draft.value?.type) && (!g.compatibility || g.fields.some(f=>draft.value?.fields?.[f.key]?.length))))
const editable=computed(()=>draft.value && draft.value.status!=='issued' && store.can('investigate',event.value))
const stageGuide=computed(()=>({'1B':{title:'Initial report',message:'Record what is known now: occurrence, involved vessels, reported consequences and initial actions. Unknown facts can remain blank.'},'2':{title:'Progress update',message:'Record what changed since the last report and the information as-of date. Keep earlier revisions for reference.'},'3B':{title:'Final investigation report',message:'Use the factual record and evidence to document findings, analysis, conclusions and recommendations. Open the detailed checklists when needed.'}}[draft.value?.type||stage.value]))
const essentialOccurrenceKeys=['occurrenceDate','occurrenceTime','place','occurrenceNarrative','informationSources']
const isOccurrence=g=>g.fields.some(f=>f.key==='occurrenceNarrative')
const groupId=g=>'report-section-'+g.title.toLowerCase().replace(/[^a-z0-9]+/g,'-')
const groupLabel=g=>g.title.replace(/^Final report · /,'').replace(/ \(Form 3B pp?[0-9–-]+\)/,'')
function resetSections(type){openSections.value=Object.fromEntries(maicGroups.map(g=>[g.title,type==='1B'?isOccurrence(g):type==='2'?g.fields.some(f=>f.key==='progressSummary'):g.fields.some(f=>f.key==='analysis')]))}
async function showSection(key){const group=groups.value.find(g=>g.fields.some(f=>f.key===key));if(!group)return;openSections.value[group.title]=true;await nextTick();document.getElementById(groupId(group))?.scrollIntoView({behavior:'smooth',block:'start'})}
const evidence=computed(()=>store.visibleRecords('evidence').filter(e=>e.eventId===event.value?.id))
function load(r){draft.value=clone(r);draft.value.fields=initializeFields(draft.value.fields || {});if(!draft.value.fields.occurrenceNarrative && draft.value.fields.narrative)draft.value.fields.occurrenceNarrative=draft.value.fields.narrative;draft.value.evidenceIds ||= [];for(const group of maicGroups)for(const f of group.fields){if(f.type==='checks' && !Array.isArray(draft.value.fields[f.key]))draft.value.fields[f.key]=[]}error.value='';success.value='';resetSections(draft.value.type)}
watch(()=>[route.params.id,route.query.reportId],()=>{const requested=reports.value.find(r=>r.id===route.query.reportId);if(requested)load(requested);else draft.value=null},{immediate:true})
function create(type,base){const revisions=reports.value.filter(r=>r.type===type);load({eventId:event.value.id,type,revision:Math.max(0,...revisions.map(r=>r.revision || 0))+1,status:'draft',date:today(),asOf:today(),preparedBy:store.currentUser.value?.name || '',designation:'Marine casualty investigator',notedBy:'',notedDate:'',fields:base ? clone(base.fields) : initialFields(event.value),evidenceIds:base ? [...(base.evidenceIds || [])] : [...(event.value.evidenceIds || [])]})}
function save(status='draft'){
 try{error.value='';success.value='';if(!store.can('investigate',event.value))throw Error('Investigation permission required.');if(draft.value.status==='issued')throw Error('Issued revisions are retained. Create a new revision to make changes.');if(status==='issued' && draft.value.status!=='review')throw Error('Save this revision for review before issuing.');if(status==='issued' && ![draft.value.date,draft.value.preparedBy,draft.value.designation,draft.value.notedBy,draft.value.notedDate].every(v=>String(v || '').trim()))throw Error('Report date, preparer, designation, noted-by and noted date are required to issue the demonstration revision.');
 const data=clone(draft.value);data.status=status;data.createdBy ||= store.currentUser.value?.id;data.createdAt ||= new Date().toISOString();data.updatedAt=new Date().toISOString();if(status==='review'){data.reviewedBy=store.currentUser.value?.id;data.reviewedAt=new Date().toISOString()}if(status==='issued'){data.issuedBy=store.currentUser.value?.id;data.issuedAt=new Date().toISOString()}for(const g of groups.value)for(const f of g.fields)if(f.type==='number'){const v=data.fields[f.key];data.fields[f.key]=v==='' || v===undefined || v===null ? null : Number(v);if(data.fields[f.key]!==null && (!Number.isInteger(data.fields[f.key]) || data.fields[f.key]<0))throw Error(`${f.label} must be a whole non-negative number or unknown.`)}
 const result=data.id ? store.update('reports',data.id,data) : store.recordReport(data);load(result);success.value=`MAIC ${result.type} revision ${result.revision} saved as ${status}.`;
 }catch(e){error.value=e.message}
}
function fieldText(f){const value=draft.value.fields[f.key];return Array.isArray(value) ? (value.map(v=>f.options?.find(o=>typeof o==='object' && o.value===v)?.label || v).join(', ') || 'Not recorded') : display(value)}
function preview(){if(!draft.value)return;const r=draft.value;printReport({title:`MAIC Form ${r.type} · ${event.value.ref}`,subtitle:`Revision ${r.revision} · ${r.status} · Demonstration / fictional data`,metadata:{reportDate:r.date,asOf:r.asOf,preparedBy:r.preparedBy,designation:r.designation,notedBy:r.notedBy,notedDate:r.notedDate,signature:'No actual signature — demonstration only'},sections:groups.value.map(g=>({title:g.title,content:g.fields.map(f=>`${f.label}: ${fieldText(f)}`).join('\n\n')})).concat([{title:'Evidence references',content:r.evidenceIds.map(id=>{const e=store.visibleRecords('evidence').find(e=>e.id===id);return e ? `${e.name} · ${e.sourceRef || 'No reference'}` : id}).join('\n') || 'No evidence linked'}])})}
function assign(id){try{store.saveEvent({...event.value,investigatorId:id});error.value=''}catch(e){error.value=e.message}}
</script>
<template><div class="page-wrap"><template v-if="event"><PageHeader title="Investigation workbench" :subtitle="`${event.ref} · ${event.type} · ${event.place || 'Location unknown'}`"><template #actions><q-btn flat no-caps label="Incident workspace" :to="`/admin/incidents/${event.id}`"/></template></PageHeader>
 <q-banner v-if="error" class="bg-red-1 text-negative q-mb-md" rounded>{{error}}</q-banner><q-banner v-if="success" class="bg-green-1 text-positive q-mb-md" rounded>{{success}}</q-banner>
 <div class="panel q-mb-md"><div class="report-start-heading"><div><div class="section-title q-mb-xs">1. Choose a report stage</div><p class="muted q-mb-none">Continue a saved revision, or create the next report.</p></div><q-select style="min-width:250px" outlined dense clearable :model-value="event.investigatorId" @update:model-value="assign" :options="investigatorOptions(store)" emit-value map-options label="Investigator"/></div><div class="toolbar-row q-mt-md q-mb-none"><q-select v-model="stage" :options="[{label:'Form 1B · Initial',value:'1B'},{label:'Form 2 · Progress',value:'2'},{label:'Form 3B · Final',value:'3B'}]" emit-value map-options outlined dense style="min-width:230px" label="New report stage"/><q-btn color="primary" no-caps icon="add" label="Create draft" @click="create(stage)"/><q-space/><q-btn flat no-caps label="Cases" :to="{path:'/admin/cases',query:{eventId:event.id}}"/><q-btn flat no-caps label="Follow-up" :to="{path:'/admin/actions',query:{eventId:event.id}}"/></div></div>
 <div class="workbench-grid"><aside class="panel"><q-expansion-item class="revision-disclosure" :model-value="$q.screen.gt.sm||revisionsOpen" @update:model-value="revisionsOpen=$event" :label="`Saved revisions (${reports.length}) and sources`" header-class="text-weight-bold"><div class="section-title">Retained revisions</div><p class="muted">Choose a draft to continue, or open an issued revision to read it.</p><q-list separator><q-item v-for="r in reports" :key="r.id" clickable @click="load(r)" :active="draft?.id===r.id" active-class="text-primary"><q-item-section><q-item-label>Form {{r.type}} · revision {{r.revision}}</q-item-label><q-item-label caption>{{r.asOf || r.date}} · {{r.preparedBy || 'Preparer pending'}}</q-item-label><StatusBadge class="q-mt-xs" :status="r.status"/></q-item-section></q-item></q-list><p v-if="!reports.length" class="muted">Create the first initial report draft.</p><q-separator class="q-my-md"/><div class="section-title">Source evidence</div><div v-for="e in evidence" :key="e.id" class="q-mb-sm"><q-icon name="description" class="q-mr-xs"/>{{e.name}}<div class="muted">{{e.sourceRef || 'Reference not supplied'}}</div></div><q-btn flat no-caps label="Manage evidence" :to="{path:'/admin/documents',query:{eventId:event.id}}"/></q-expansion-item></aside>
 <section class="panel report-editor" v-if="draft"><div class="toolbar-row"><div><div class="section-title">MAIC Form {{draft.type}} · revision {{draft.revision}}</div><StatusBadge :status="draft.status"/></div><q-space/><q-btn outline no-caps icon="print" label="Preview / print" @click="preview"/><q-btn v-if="draft.id" flat no-caps label="New revision" @click="create(draft.type,draft)"/></div><q-banner v-if="draft.status==='issued'" rounded class="q-mt-md bg-blue-1 text-primary">Issued revisions are retained. Use New revision to record a subsequent progress update or amendment.</q-banner><section class="stage-guidance q-mt-lg"><div class="text-weight-bold">2. Complete the {{stageGuide.title.toLowerCase()}}</div><p class="muted q-mt-xs q-mb-sm">{{stageGuide.message}}</p><div class="row q-gutter-xs"><q-btn v-if="draft.type!=='2'" flat dense no-caps color="primary" label="Occurrence" @click="showSection('occurrenceNarrative')"/><q-btn v-if="draft.type==='2'" flat dense no-caps color="primary" label="Progress update" @click="showSection('progressSummary')"/><q-btn flat dense no-caps color="primary" label="Consequences" @click="showSection('fatalities')"/><q-btn v-if="draft.type==='3B'" flat dense no-caps color="primary" label="Causes and findings" @click="showSection('machineryFailures')"/><q-btn v-if="draft.type==='3B'" flat dense no-caps color="primary" label="Analysis" @click="showSection('analysis')"/><q-btn flat dense no-caps color="primary" label="Recommendations" @click="showSection('recommendations')"/></div></section><q-form @submit="save('draft')" class="q-mt-lg"><fieldset :disabled="!editable" class="report-fieldset"><h3 class="section-title">Report dates and sign-off</h3><div class="form-grid"><q-input v-model="draft.date" outlined type="date" stack-label label="Report date"/><q-input v-model="draft.asOf" outlined type="date" stack-label label="Information as of"/><q-input v-model="draft.preparedBy" outlined label="Prepared by"/><q-input v-model="draft.designation" outlined label="Designation"/><q-input v-model="draft.notedBy" outlined label="Noted by / director"/><q-input v-model="draft.notedDate" outlined type="date" stack-label label="Noted date"/></div><q-select class="q-mt-md" v-model="draft.evidenceIds" multiple use-chips outlined :options="evidence.map(e=>({label:e.name,value:e.id}))" emit-value map-options label="Linked evidence metadata"/>
 <q-banner v-if="draft.type==='3B'" rounded class="q-mt-md bg-blue-1 text-primary">Select only findings supported by evidence. An unchecked box means no finding recorded. Leave unknown crew/passenger allocations blank.</q-banner>
 <q-expansion-item v-for="g in groups" :key="`${draft.type}-${draft.id||'new'}-${g.title}`" :id="groupId(g)" :model-value="!!openSections[g.title]" @update:model-value="openSections[g.title]=$event" :label="groupLabel(g)" header-class="text-weight-bold" class="report-section q-mt-md"><div class="q-pa-sm"><template v-if="isOccurrence(g)"><ReportFields :definitions="g.fields.filter(f=>essentialOccurrenceKeys.includes(f.key))" :values="draft.fields" :editable="editable"/><q-expansion-item label="Classification, position and office details" icon="tune" class="q-mt-md"><ReportFields class="q-pa-sm" :definitions="g.fields.filter(f=>!essentialOccurrenceKeys.includes(f.key))" :values="draft.fields" :editable="editable"/></q-expansion-item></template><ReportFields v-else :definitions="g.fields" :values="draft.fields" :editable="editable"/></div></q-expansion-item></fieldset>
 <p class="muted text-caption q-mt-md">Saving this report preserves its own revision. Correct event totals in the incident workspace when required; progress reports do not add new casualty totals.</p><div class="report-save-actions" v-if="editable"><div class="text-weight-bold">3. Save, review and issue</div><div class="toolbar-row q-mt-sm q-mb-none"><q-btn color="primary" no-caps type="submit" label="Save draft"/><q-btn outline no-caps label="Save for review" @click="save('review')"/><q-btn v-if="draft.status==='review'" color="positive" no-caps label="Issue demonstration revision" @click="save('issued')"/></div><p class="text-caption muted q-mt-sm q-mb-none">Save a draft at any time. Issuing requires a saved review state and completed sign-off details.</p></div></q-form></section>
 <section class="panel" v-else><q-icon name="fact_check" size="44px" color="primary"/><h2 class="text-h6">Choose a report revision</h2><p class="muted">Create a draft to prepare initial findings, a repeatable progress update or the final investigation report.</p><q-btn color="primary" no-caps label="Create initial report" @click="create('1B')"/></section></div></template><section v-else class="panel"><h2>Investigation unavailable</h2><p>The incident does not exist or is outside your scope.</p><q-btn to="/admin/investigations" label="Back to investigations" no-caps color="primary"/></section></div></template>
<style scoped>.report-start-heading{display:flex;justify-content:space-between;gap:20px;align-items:center}.stage-guidance{background:var(--ss-soft,#f1f5f9);border:1px solid var(--ss-border,#e2e5ea);border-radius:10px;padding:16px}.report-section{border:1px solid var(--ss-border,#e2e5ea);border-radius:10px;scroll-margin-top:100px}.report-save-actions{position:sticky;bottom:12px;background:var(--ss-card,#fff);border:1px solid var(--ss-border,#e2e5ea);border-radius:10px;padding:16px;margin-top:22px;box-shadow:0 4px 15px #12303b0b;z-index:2}.report-editor{min-width:0}.revision-disclosure :deep(.q-expansion-item__content){padding-top:8px}.workbench-grid{display:grid;grid-template-columns:280px minmax(0,1fr);gap:20px;align-items:start}.report-fieldset{border:0;margin:0;padding:0;min-width:0}@media(min-width:1024px){.revision-disclosure :deep(.q-expansion-item__container>.q-item){display:none}}@media(max-width:1000px){.workbench-grid{grid-template-columns:1fr}.report-start-heading{align-items:flex-start;flex-direction:column}}@media(max-width:600px){.report-save-actions{position:static}.report-start-heading .q-field{min-width:0!important;width:100%}}</style>
